/**
 * @param {string} firstWord
 * @param {string} secondWord
 * @param {string} targetWord
 * @return {boolean}
 */
 var isSumEqual = function(firstWord, secondWord, targetWord) {
    let carry = 0;
    let n1 = firstWord.length, n2 = secondWord.length;
    let n3 = targetWord.length;
    for (let i = 0; i < n3; i++) {
        let num1 = getNum(firstWord.charAt(n1 - 1 - i));
        let num2 = getNum(secondWord.charAt(n2 - 1 - i));
        let sum = carry + num1 + num2;
        if (getNum(targetWord.charAt(n3 - 1 - i)) != (sum % 10)) return false;
        carry = parseInt(sum / 10);
    }
    return true;
};

function getNum (char) {
    if (!char) return 0;
    return char.charCodeAt() - 'a'.charCodeAt();
}

package io.github.leetcode.strings;

public class CheckIfWordEqualsSummationOfTwoWords {

    public boolean isSumEqual(String firstWord, String secondWord, String targetWord) {
        int s1 = 0, s2 = 0, s3 = 0;

        for (int i = 0; i < firstWord.length(); i++) {
            s1 = (firstWord.charAt(i) - 'a') + s1 * 10;
        }

        for (int i = 0; i < secondWord.length(); i++) {
            s2 = (secondWord.charAt(i) - 'a') + s2 * 10;
        }

        for (int i = 0; i < targetWord.length(); i++) {
            s3 = (targetWord.charAt(i) - 'a') + s3 * 10;
        }

        return s1 + s2 == s3;
    }

}
